'use strict';
/* effects/app-icons.js — PWA icons/meta + data-img wiring */
(function(){
  try{
    var hd=document.head;
    function link(rel,sizes,href){var l=document.createElement('link');l.rel=rel;if(sizes)l.setAttribute('sizes',sizes);l.href=href;hd.appendChild(l)}
    function meta(n,c){var m=document.createElement('meta');m.name=n;m.content=c;hd.appendChild(m)}
    link('icon','192x192','data:image/png;base64,');
    link('apple-touch-icon','180x180','data:image/png;base64,');
    meta('apple-mobile-web-app-title','Budget Book');
    meta('apple-mobile-web-app-capable','yes');
    meta('theme-color','#090909');
  }catch(e){}
})();
document.querySelectorAll('[data-img]').forEach(function(el){el.src=IMG[el.getAttribute('data-img')]});
